{
  "issues": [
    {
      "id": "evaluator_execution_scope",
      "evidence": "All three calls fail immediately after name confirmation, before any bank operation. The supplied traces do not include the underlying Python exception.",
      "problem": "The evaluator defines helpers that depend on script-level state and uses global prefix inside those helpers. That is unsafe when the executor wraps the snippet or executes it with separate global and local namespaces. The exception handler then hides the cause.",
      "fix": "Place evaluator state, imports and helpers inside one explicitly invoked function. Use a mutable closure for accumulated speech, remove global declarations, and retain a private diagnostic on failure."
    },
    {
      "id": "unrecoverable_error_conversation",
