    },
    {
      "id": "authorization_before_account_loading",
      "problem": "A human request received around the final successful security result can enter the help-first conversation while authorization is complete but account data is absent. The current evaluator treats that legitimate intermediate state as a technical failure.",
      "fix": "Process help-first replies before requiring loaded account data. Fetch the account only after authorization; permit a general human transfer without an account lookup."
    },
    {
      "id": "repeated_floor_and_help_offers",
      "problem": "A floor rejected during proposal confirmation can be offered again as attempt 1, despite the floor-once rule. Ambiguous replies to the human question also cause the help-first question to be repeated indefinitely.",
      "fix": "Track rejected floor offers independently from persuasion attempts. Only late-band attempt 2 may repeat the floor. Ask the help-first question once and preserve any substantive answer supplied afterward."
    },
    {
      "id": "validation_limits",
      "problem": "The previous checks did not establish that the evaluator could run in the platform execution scope. Several checks also asserted speech without inspecting computed deadlines.",
      "fix": "Append startup, recovery, authorization, band-edge, split-answer and write-sequence regression checks. These are authored checks, not executed test results. The source still supplies no alternative successful closing protocol for a failed close_call; do not fabricate one or retry that operation silently."
    }
  ],
  "patches": [
    {
      "op": "add",
      "path": "/workflow/nodes/opening/extraction_schema/-",
      "value": {
